 \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"~4.0.4\",\n    \"@deepseek-ai/dsh-fs\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-shell\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-spill\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-subprocess\": \"0.2.0-rc.2\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"~4.0.4\",\n    \"@deepseek-ai/dsh-fs\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-shell\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-spill\": \"0.2.0-rc.2\",\n    \"tsup\": \"^8.5.0\",\n    \"typescript\": \"^6.0.0\",\n    \"vitest\": \"^4.1.12\",\n    \"@deepseek-ai/dsh-subprocess\": \"0.2.0-rc.2\"\n  }\n}\n"
