      "path": "typescript/packages/dsh/cordis.patch.yml",
      "content": "# The mirage bundle patch. Applied over dsh-base by `dsh --profile <name>`\n# after `dsh plugin --profile <name> add @struktoai/mirage-dsh`: it swaps\n# the filesystem and shell providers for mirage-backed ones, so dsh's file\n# tools and bash tool operate on a workspace of mounted VFS instead\n# of the host disk.\n#\n# Override the `mirage` row's config in the profile's own cordis.patch.yml\n# to mount real VFS (the block form is `vfs` registry name,\n# `mode`, and the VFS's `config`; `!!js` expressions resolve env vars\n# at mount time):\n#\n#   - id: mirage\n#     config:\n#       mounts:\n#         /tmp: { VFS: ram, mode: exec }\n#         /slack:\n#           VFS: slack\n#           mode: read\n#           config: { token: !!js process.env.SLACK_BOT_TOKEN }\n#       runtimes:\n#         - { name: monty, captures: [python, python3] }\n#\n# A profile may also carry a permission document, which is what turns\n# mirage's allow/ask/deny into a policy for this bundle. Roles go under\n# `profiles`, and `profile` names the one a session gets by default:\n#\n#   - id: mirage\n#     config:\n#       profiles:\n#         agent:\n#           commands:\n#             allow: [cat, ls, grep, rm]\n#             ask:\n#               - { commands: [rm], reason: deletes are reviewed }\n#             deny:\n#               - { commands: [git push], reason: no publishing }\n#       profile: agent\n#\n# An `ask` rule is put to the human through dsh's own approval channel\n# (`ctx.approval`), so the prompt the agent triggers is the one dsh\n# already shows for its escalations. It quotes the line word by word as\n# a shell would read it back, so a name carrying a space or a newline\n# cannot pass itself off in the prompt as two operands or two lines.\n# `allowed-once` runs the line;\n# a rejection, a dismissal and an unanswerable ask all refuse it. With\n# no approval plugin composed the ask has nowhere to go, so it stays a\n# pending record the host answers through `ctx.mirage.decisions`\n# (`pending()`, then `answer(id, outcome, scope)`) — deliberately not a\n# refusal, since rewriting an `ask` rule as a `deny` would change what\n# the document says. A question never outlives the run that raised it:\n# the run's abort signal goes to the channel with the request and bounds\n# the ledger's wait, so a line still unanswered when its timeout expires\n# comes back as the kill, and a yes arriving after that is dropped\n# rather than banked for the next identical line.\n#\n# Two facts about how the mirage providers read the surrounding dsh\n# composition, neither of which needs a row here:\n#\n#   * The standing file policy is enforced, not merely reported. Both\n#     seams narrow every mount grant to read for a `read-only` call\n#     (leaving the null sink writable, as that mode's definition\n#     requires), so dsh-base's `DSH_PERMISSION_MODE=read-only` now\n#     actually confines a mirage world instead of being ignored. The\n#     policy's `workspaceRoot` is a directory on the host and is never\n#     consulted: the mounts and their modes are the boundary here.\n#\n#   * A workdir dsh resolved on its own machine (an unspecified one\n#     comes from the calling session's cwd) names nothing in this world,\n#     so it is ignored in favour of the workspace default rather than\n#     run in a directory the agent cannot reach.\n#\n# ctx.subprocess shares the workspace's argv admission and process supervisor.\n# Termination covers managed Mirage runners. Native OS descendant tracking and\n# PTYs are unsupported; this provider refuses worlds with native/remote reach.\n- id: subprocess\n  disabled: true\n\n# The host filesystem and bash providers step aside; mirage provides the\n# same ctx.fs and ctx.shell seams over the workspace.\n- id: fs-sandbox\n  disabled: true\n\n- id: bash-sandbox\n  disabled: true\n\n# PowerShell and the ripgrep-based search tool run host subprocesses,\n# which the mirage world does not contain; the bash tool's grep covers\n# search inside the workspace.\n- id: pwsh-sandbox\n  disabled: true\n\n- id: tool-pwsh\n  disabled: true\n\n- id: tool-fs-search\n  disabled: true\n\n# Oversized tool results spill to the workspace, not to the host.\n#\n# The spill policy keeps a result over `maxInlineBytes` out of the\n# model's context by saving the full text and replacing the result with\n# a preview plus the locator, telling the model to read or grep it for\n# the rest. dsh-base stores that through `spill-local`, which writes\n# under the host's temporary directory — a path that names nothing in\n# this world, so the recovery the notice invites fails on a file the\n# model cannot open, and an oversized result becomes truncation with a\n# dead pointer. The mirage store writes through the same dispatcher every\n# other effect here passes, so the locator is an ordinary workspace path\n# and the tool that produced the output is the one that can go read it.\n#\n# `dir` moves the artifacts; the default rides the `/tmp` ram mount\n# below. A deployment that wants them out of the agent's reach puts\n# `dir` on a mount the session holds no grant for — mirage has no\n# permission bits to offer, so the mount table is the boundary.\n- id: spill-local\n  disabled: true\n\n- insert:\n    - id: mirage\n      name: '@struktoai/mirage-dsh/service'\n      config:\n        mounts:\n          /tmp: { vfs: ram, mode: exec }\n\n    - id: mirage-fs\n      name: '@struktoai/mirage-dsh/fs'\n\n    - id: mirage-subprocess\n      name: '@struktoai/mirage-dsh/subprocess'\n\n    - id: mirage-shell\n      name: '@struktoai/mirage-dsh/shell'\n\n    - id: mirage-spill\n      name: '@struktoai/mirage-dsh/spill-store'\n"
    },
    {
      "path": "typescript/packages/dsh/src/service.ts",
      "content": "// ========= Copyright 2026 @ Strukto.AI All Rights Reserved. =========\n// Licensed under the Apache License, Version 2.0 (the \"License\");\n// you may not use this file except in compliance with the License.\n// You may obtain a copy of the License at\n//\n//     http://www.apache.org/licenses/LICENSE-2.0\n//\n// Unless required by applicable law or agreed to in writing, software\n// distributed under the License is distributed on an \"AS IS\" BASIS,\n// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n// See the License for the specific language governing permissions and\n// limitations under the License.\n// ========= Copyright 2026 @ Strukto.AI All Rights Reserved. =========\n\nimport { Service } from '@deepseek-ai/cordis'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { ShellExplanation } from '@struktoai/mirage-core/policy/types'\nimport type { Runtime, RuntimeEntry } from '@struktoai/mirage-core/runtime/base'\nimport { buildRuntime } from '@struktoai/mirage-core/runtime/table'\nimport { parseMountMode } from '@struktoai/mirage-core/types'\nimport { snakeToCamel } from '@struktoai/mirage-core/utils/normalize'\nimport { Mount } from '@struktoai/mirage-core/workspace/mount/spec'\nimport type { MountSpec } from '@struktoai/mirage-core/workspace/workspace/workspace'\nimport { Workspace, buildVfs, parseSessionProfile } from '@struktoai/mirage-node'\nimport type { NodeWorkspaceOptions, SessionProfile } from '@struktoai/mirage-node'\nimport { askThroughApproval } from './approval.ts'\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Context {\n    mirage: MirageService\n  }\n}\n\n/**\n * A declarative mount, YAML-friendly: the VFS is named by its\n * registry type and built through `buildVfs`, so a dsh bundle\n * patch can mount anything without holding a live instance. Told apart\n * from a live `Mount` by the type of `vfs`: a string names a\n * registry entry, an object is the instance itself.\n */\nexport interface MirageMountBlock {\n  /** VFS registry name (`ram`, `s3`, `slack`, `redis`, ...). */\n  vfs: string\n  /** Mount mode: `read`, `write`, or `exec`. Omitted = the workspace default. */\n  mode?: string\n  /** VFS constructor config, passed to the registry factory. */\n  config?: Record<string, unknown>\n}\n\n/** One mount entry: a live spec or instance, or a declarative block. */\nexport type MirageMount = MountSpec | Mount | MirageMountBlock\n\n/** A runtime entry, YAML-friendly: a name, or a name with its options. */\nexport interface MirageRuntimeBlock {\n  /** Runtime registry name (`monty`, `pyodide`, `quickjs`, ...). */\n  name: string\n  /** Command words this runtime captures (e.g. `['python', 'python3']`). */\n  captures?: string[]\n  /** The runtime's own config block; a key it does not have is refused. */\n  config?: Record<string, unknown>\n}\n\n/**\n * Configuration for the shared mirage execution world. Exactly one of\n * `workspace` (adopt a live workspace the embedder owns and closes) or\n * `mounts` (construct a workspace here; the service closes it when its\n * plugin unloads) must be given.\n */\nexport interface MirageConfig {\n  /** A live workspace to adopt; its lifecycle stays with the embedder. */\n  workspace?: Workspace\n  /** Mounts for a service-owned workspace, keyed by mount prefix. */\n  mounts?: Record<string, MirageMount>\n  /**\n   * Runtimes for a service-owned workspace, built via `buildRuntime`.\n   * The YAML-friendly twin of `workspaceOptions.runtimes`; pass one or\n   * the other, not both.\n   */\n  runtimes?: (string | MirageRuntimeBlock)[]\n  /**\n   * The roles (`profiles:` in mirage config), each a whole permission\n   * document: its `commands.allow` list, its `commands.ask` and\n   * `commands.deny` rules, the mount sections carrying rules of their\n   * own, and the paths and vars it hides. The YAML-friendly twin of\n   * `workspaceOptions.profiles`; pass one or the other, not both.\n   *\n   * Written as the document, not as an already-parsed profile: every\n   * entry goes through `parseSessionProfile`, so a misspelled field is a\n   * load error rather than a first-session one. That parse is what lets\n   * a dsh bundle patch carry a policy at all, since\n   * `workspaceOptions.profiles` wants profiles already parsed and a\n   * patch file holds plain YAML.\n   */\n  profiles?: Record<string, unknown>\n  /**\n   * Which role shapes a session created without one, the workspace's own\n   * session included. A name `profiles` does not define is an error. The\n   * YAML-friendly twin of `workspaceOptions.profile`.\n   */\n  profile?: string\n  /** Options forwarded to the service-owned workspace's constructor. */\n  workspaceOptions?: NodeWorkspaceOptions\n}\n\nfunction isMountBlock(entry: MirageMount): entry is MirageMountBlock {\n  if (Array.isArray(entry)) return false\n  return typeof (entry as MirageMountBlock).vfs === 'string'\n}\n\nasync function resolveMount(entry: MirageMountBlock): Promise<MountSpec> {\n  const vfs = await buildVfs(entry.vfs, entry.config ?? {})\n  return new Mount(vfs, {\n    ...(entry.mode !== undefined ? { mode: parseMountMode(entry.mode) } : {}),\n    vfsRef: entry.vfs,\n  })\n}\n\n/**\n * Validate a `profiles` block: every role through the core document\n * validator, naming the role in the error so a typo in a patch file\n * points at the block that holds it.\n *\n * @param raw the roles as written, keyed by role name.\n * @returns the parsed roles, ready for `WorkspaceOptions.profiles`.\n */\nfunction parseProfiles(raw: Record<string, unknown>): Record<string, SessionProfile> {\n  const out: Record<string, SessionProfile> = {}\n  for (const [name, block] of Object.entries(raw)) {\n    out[name] = parseSessionProfile(block, `profile \\`${name}\\``)\n  }\n  return out\n}\n\n// A config block is snake_case, as in a workspace file; the runtime's\n// own keys are camelCase. Only the keys: values pass through untouched.\nfunction camelKeys(block: Record<string, unknown>): Record<string, unknown> {\n  return Object.fromEntries(Object.entries(block).map(([key, value]) => [snakeToCamel(key), value]))\n}\n\nfunction toRuntimeEntry(entry: string | MirageRuntimeBlock): RuntimeEntry {\n  if (typeof entry === 'string') return entry\n  const { name, config, ...options } = entry\n  return buildRuntime(\n    name,\n    config === undefined ? options : { ...options, config: camelKeys(config) },\n  )\n}\n\n// A name shorthand builds exactly as the workspace would build it; holding\n// the instance early is what lets `vfsOnly` classify the world before the\n// (asynchronous) mounts finish resolving.\nfunction builtEntry(entry: RuntimeEntry): Runtime {\n  return typeof entry === 'string' ? buildRuntime(entry) : entry\n}\n\n/**\n * The one mirage `Workspace` behind every mirage-backed dsh provider\n * (`ctx.mirage`, mirroring how `ctx.e2b` owns one sandbox for the E2B\n * adapters). `MirageFileSystem` and `MirageShellExecutor` both inject it,\n * which is what keeps `ctx.fs` targets and `ctx.shell` commands in one\n * execution world: a `processPath` handed to the shell resolves there.\n *\n * Construction with live mounts is synchronous; a declarative mount\n * block defers to `buildVfs`, so consumers await `ready` (the\n * adapters do) and `workspace` throws until it resolves, mirroring how\n * the E2B service owner exposes its sandbox.\n */\nexport class MirageService extends Service {\n  static readonly provide = 'mirage'\n\n  /** Resolves to the shared workspace once every mount is built. */\n  readonly ready: Promise<Workspace>\n\n  private built: Workspace | null = null\n  private readonly plannedRuntimes: readonly Runtime[] | undefined\n\n  constructor(ctx: Context, config: MirageConfig = {}) {\n    super(ctx, 'mirage')\n    if (config.workspace !== undefined && config.mounts !== undefined) {\n      throw new Error('mirage: pass either workspace or mounts, not both')\n    }\n    if (config.workspace !== undefined) {\n      // An adopted workspace is already built, so runtimes and constructor\n      // options can no longer reach it. Saying so beats accepting a config\n      // whose runtimes silently never load, which is what the workspace and\n      // mounts pair above already refuses to do.\n      // `profiles` and `profile` join them for the same reason, and one\n      // more: an adopted workspace's roles and its `onAsk` are the\n      // embedder's own, so silently re-answering its asks through\n      // `ctx.approval` would take over a seam it may already have filled.\n      if (\n        config.runtimes !== undefined ||\n        config.workspaceOptions !== undefined ||\n        config.profiles !== undefined ||\n        config.profile !== undefined\n      ) {\n        throw new Error(\n          'mirage: runtimes, profiles, profile and workspaceOptions configure a service-owned workspace, not an adopted workspace',\n        )\n      }\n      this.built = config.workspace\n      this.ready = Promise.resolve(config.workspace)\n      return\n    }\n    if (config.mounts === undefined) {\n      throw new Error('mirage: one of workspace or mounts is required')\n    }\n    const options = { ...(config.workspaceOptions ?? {}) }\n    if (config.runtimes !== undefined) {\n      if (options.runtimes !== undefined) {\n        throw new Error('mirage: pass runtimes or workspaceOptions.runtimes, not both')\n      }\n      options.runtimes = config.runtimes.map(toRuntimeEntry)\n    }\n    if (config.profiles !== undefined) {\n      if (options.profiles !== undefined) {\n        throw new Error('mirage: pass profiles or workspaceOptions.profiles, not both')\n      }\n      options.profiles = parseProfiles(config.profiles)\n    }\n    if (config.profile !== undefined) {\n      if (options.profile !== undefined) {\n        throw new Error('mirage: pass profile or workspaceOptions.profile, not both')\n      }\n      options.profile = config.profile\n    }\n    // How an asked line gets answered. Installed for every service-owned\n    // workspace rather than only under a composed `ctx.approval`, because\n    // the two are one answer to mirage (an unset `onAsk` and a handler\n    // returning null both leave the ask pending) and installing always is\n    // what finds an approver composed after this plugin. An explicit\n    // `workspaceOptions.onAsk` is the embedder's decision and stands.\n    options.onAsk ??= askThroughApproval(ctx)\n    this.plannedRuntimes = options.runtimes?.map(builtEntry)\n    if (this.plannedRuntimes !== undefined) options.runtimes = [...this.plannedRuntimes]\n    const blocks = Object.values(config.mounts).some(isMountBlock)\n    if (blocks) {\n      this.ready = this.open(config.mounts, options)\n      // A declarative mount resolves asynchronously and nothing awaits\n      // `ready` until a provider's first call, so a failure here would\n      // reach the process as an unhandled rejection and take the whole\n      // harness down over a typo in a patch file. This only marks the\n      // rejection observed; `ready` still rejects for every real caller,\n      // and the disposer below still sees it.\n      void this.ready.catch(() => undefined)\n    } else {\n      const owned = new Workspace(config.mounts as Record<string, MountSpec | Mount>, options)\n      this.built = owned\n      this.ready = Promise.resolve(owned)\n    }\n    ctx.effect(\n      () => async () => {\n        const ws = await this.ready.catch(() => null)\n        if (ws !== null) await ws.close()\n      },\n      'mirage workspace',\n    )\n  }\n\n  /** The live workspace; throws until `ready` resolves. */\n  get workspace(): Workspace {\n    if (this.built === null) {\n      throw new Error('mirage: workspace is not ready yet; await ctx.mirage.ready')\n    }\n    return this.built\n  }\n\n  /**\n   * The live workspace, or null while it is still building.\n   *\n   * The non-throwing twin of {@link workspace}, for a synchronous seam\n   * method whose honest answer before `ready` is \"this world cannot tell\n   * you\" rather than an exception. Reads `built` directly, as\n   * {@link vfsOnly} does.\n   */\n  get workspaceIfReady(): Workspace | null {\n    return this.built\n  }\n\n  /**\n   * The decision ledger: every ask this world has raised and every\n   * answer given, questions still waiting included.\n   *\n   * The host's handle on the ask layer. A composition with an approval\n   * channel answers inline and rarely reads this; one without it finds\n   * its pending questions here (`pending()`) and answers them out of\n   * band (`answer(id, outcome, scope)`), which is what makes an `ask`\n   * rule usable with no human at the keyboard.\n   */\n  get decisions(): Workspace['decisions'] {\n    return this.workspace.decisions\n  }\n\n  /**\n   * What a line would do here, without doing it: the line's verdict, with\n   * the exact exit code and stderr the agent would get, and its parse tree,\n   * every command carrying its own outcome and the policies that spoke.\n   *\n   * A dry run through the same gate the dispatcher uses, so a host\n   * reading this and an agent typing the line cannot be told different\n   * things. It spends no ONCE answer, records no question and never\n   * reaches the approval channel, which is what makes it safe to call\n   * about a line nobody typed — a pre-execute check, or an operator\n   * asking why a command was refused.\n   *\n   * @param line the command line to judge.\n   * @param sessionId the session to judge it in; the default when empty.\n   * @returns the line's explanation.\n   */\n  async explain(line: string, sessionId = ''): Promise<ShellExplanation> {\n    const ws = await this.ready\n    return ws.explain(line, sessionId)\n  }\n\n  /**\n   * True while every runtime in the world reaches only the vfs\n   * (`Runtime.reach`), meaning the workspace dispatch is the single\n   * gate for anything the agent can execute: every effect passes\n   * mount modes, session grants, and policy before touching the real\n   * backend behind a mount. The default world qualifies, and so do\n   * the bridged engines, while the host `local` python or a remote\n   * sandbox can act around the gate. Answers before `ready` from the\n   * constructor-resolved entries (mounts resolve asynchronously,\n   * runtimes never do) and from the live workspace afterwards, so a\n   * later `addRuntime` or `removeRuntime` is seen.\n   */\n  get vfsOnly(): boolean {\n    const entries = this.built === null ? (this.plannedRuntimes ?? []) : this.built.runtimes()\n    return entries.every((entry) => entry.reach === 'workspace')\n  }\n\n  private async open(\n    mounts: Record<string, MirageMount>,\n    options: NodeWorkspaceOptions,\n  ): Promise<Workspace> {\n    const resolved: Record<string, MountSpec | Mount> = {}\n    for (const [prefix, entry] of Object.entries(mounts)) {\n      resolved[prefix] = isMountBlock(entry) ? await resolveMount(entry) : entry\n    }\n    const ws = new Workspace(resolved, options)\n    this.built = ws\n    return ws\n  }\n}\n"
    },
    {
      "path": "typescript/packages/dsh/src/fs.ts",
      "content": "// ========= Copyright 2026 @ Strukto.AI All Rights Reserved. =========\n// Licensed under the Apache License, Version 2.0 (the \"License\");\n// you may not use this file except in compliance with the License.\n// You may obtain a copy of the License at\n//\n//     http://www.apache.org/licenses/LICENSE-2.0\n//\n// Unless required by applicable law or agreed to in writing, software\n// distributed under the License is distributed on an \"AS IS\" BASIS,\n// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n// See the License for the specific language governing permissions and\n// limitations under the License.\n// ========= Copyright 2026 @ Strukto.AI All Rights Reserved. =========\n\nimport { Buffer } from 'node:buffer'\nimport { isAbsolute, posix, relative, resolve, sep } from 'node:path'\nimport type { Context } from '@deepseek-ai/cordis'\nimport { FileSystem, FsError, FsTargetKey, FsVersion } from '@deepseek-ai/dsh-fs'\nimport type {\n  FsDirEntry,\n  FsEditOutcome,\n  FsEditRequest,\n  FsInfo,\n  FsPathInfo,\n  FsTarget,\n  FsWriteIntent,\n  FsWriteOutcome,\n} from '@deepseek-ai/dsh-fs'\nimport { DiskVFS } from '@struktoai/mirage-node'\nimport type { MountEntry } from '@struktoai/mirage-core/workspace/mount/mount'\nimport { Session } from '@struktoai/mirage-core/workspace/workspace/workspace'\nimport { type Files, readerOf } from '@struktoai/mirage-core/workspace/files'\nimport type { NamespaceLinks } from '@struktoai/mirage-core/view/types'\nimport { FileType } from '@struktoai/mirage-core/types'\nimport type { FileStat } from '@struktoai/mirage-core/types'\nimport { isMissingPath } from '@struktoai/mirage-core/errors/fs'\nimport { posixNormpath } from '@struktoai/mirage-core/utils/path'\nimport { compareCodePoints } from '@struktoai/mirage-core/utils/sort'\nimport { assertNotAborted, mapMirageError } from './errors.ts'\nimport {\n  applyLiteralEdit,\n  decodeStrictText,\n  detectsCrlf,\n  normalizeLineEndings,\n  restoreLineEndings,\n} from './text.ts'\n\n// Read off the seam's own signature rather than imported: the policy type\n// lives in `@deepseek-ai/dsh-sandbox`, which reaches this package only as a\n// transitive dependency of dsh-fs, and naming a fourth exact-pinned peer to\n// spell one parameter would couple the adapter to a package it never calls.\ntype SandboxPolicy = Parameters<FileSystem['writeText']>[4]\n\nconst DEFAULT_DIFF_BASIS_MAX_BYTES = 10 * 1024 * 1024\n\n/** Configuration for the mirage filesystem backend. */\nexport interface MirageFsConfig {\n  /** Virtual base directory for relative paths. Defaults to `/`. */\n  cwd?: string\n  /**\n   * Read and write as this named workspace session, so the profile\n   * that confines the session's shell confines its file tools too. The\n   * workspace's default session otherwise.\n   */\n  sessionId?: string\n  /** Exclusive byte limit on each overwrite-diff side. Defaults to 10 MiB. */\n  diffBasisMaxBytes?: number\n}\n\n// The freshness token behind FsVersion. Backends that report a fingerprint\n// or revision get a content-derived token; the rest fall back to metadata\n// (modified + size), and a backend reporting neither yields a constant, so\n// stale guards degrade to always-fresh there instead of always-stale.\nfunction versionOf(stat: FileStat): FsVersion {\n  if (stat.fingerprint !== null) return FsVersion(`fp:${stat.fingerprint}`)\n  if (stat.revision !== null) return FsVersion(`rev:${stat.revision}`)\n  if (stat.modified !== null || stat.size !== null) {\n    return FsVersion(`meta:${stat.modified ?? ''}:${String(stat.size ?? '')}`)\n  }\n  return FsVersion('unversioned')\n}\n\nfunction typeOf(stat: FileStat): FsInfo['type'] {\n  switch (stat.type) {\n    case FileType.DIRECTORY:\n      return 'directory'\n    case FileType.SYMLINK:\n      return 'other'\n    default:\n      return 'file'\n  }\n}\n\nasync function* singleChunk(text: string): AsyncGenerator<string, void, void> {\n  yield await Promise.resolve(text)\n}\n\nfunction tooLarge(displayPath: string, maxBytes: number, size?: number): FsError {\n  const found = size === undefined ? '' : `${String(size)} bytes `\n  return new FsError(\n    `cannot read \"${displayPath}\": ${found}exceeds the ${String(maxBytes)} byte cap`,\n    'FS_TOO_LARGE',\n  )\n}\n\n/**\n * Whether a `relative()` result leaves the directory it was taken from.\n *\n * Only a bare `..` or a leading `..` SEGMENT escapes: a name may itself\n * begin with two dots (`..draft`), and testing the prefix alone reads\n * that ordinary file as an escape.\n *\n * @param rel the result of `relative(root, target)`.\n * @returns true when the target lies outside the root.\n */\nfunction escapesRoot(rel: string): boolean {\n  // An absolute answer means there was no relative route at all, which on\n  // win32 is a different drive.\n  return rel === '..' || rel.startsWith(`..${sep}`) || isAbsolute(rel)\n}\n\n/**\n * The prefix of the mount a virtual path actually dispatches to.\n *\n * The deepest mount whose prefix covers the path wins, which is the rule\n * dispatch itself follows; a mount nested inside another's tree owns its\n * subtree outright.\n *\n * @param virtual an absolute virtual path.\n * @param mounts the workspace's mount table.\n * @returns the winning mount's prefix, or undefined when none covers it.\n */\nfunction ownerPrefixOf(virtual: string, mounts: readonly MountEntry[]): string | undefined {\n  const probe = virtual.endsWith('/') ? virtual : `${virtual}/`\n  let winner: string | undefined\n  for (const mount of mounts) {\n    if (!probe.startsWith(mount.prefix)) continue\n    if (winner === undefined || mount.prefix.length > winner.length) winner = mount.prefix\n  }\n  return winner\n}\n\n/**\n * Whether a namespace symlink stands between a virtual path and the backend.\n *\n * `follow` resolves link components including the final one, so a path it\n * rewrites is one an ordinary read would send somewhere else. A chain it\n * refuses to resolve (a cycle) is not mappable either, and is declined\n * rather than raised: this is a lookup, and the honest answer to \"does\n * this host file have a virtual path\" is then no.\n *\n * @param links the namespace link table, or null when none is wired.\n * @param virtual the candidate virtual path.\n * @returns true when the path must not be offered.\n */\nfunction shadowedByLink(links: NamespaceLinks | null, virtual: string): boolean {\n  if (links === null) return false\n  try {\n    return links.follow(virtual) !== virtual\n  } catch {\n    return true\n  }\n}\n\n/**\n * Mirage-backed implementation of `ctx.fs`. Targets are canonical virtual\n * paths (namespace symlinks followed), every operation walks the workspace\n * dispatcher — session grants, admission policies, cache read-through and\n * post-write invalidation all fire exactly as they do for a shell command —\n * and `processPath` answers in the same virtual path space the mirage shell\n * executes in, so the two providers share one execution world.\n *\n * One limit worth stating: mirage's `ws.vfs` takes no `AbortSignal`, so\n * cancellation is honored at this adapter's own boundaries (before a\n * dispatch, between listing entries) and not inside a single op. A long\n * read from a remote backend therefore runs to completion after the\n * signal fires, and the caller learns of the abort when it returns.\n */\nexport class MirageFileSystem extends FileSystem {\n  static readonly inject = ['mirage']\n\n  private fsOps: Files | null = null\n  private readonly cwd: string\n  private readonly sessionId: string | undefined\n  private readonly diffBasisMaxBytes: number\n  // Per-targetKey tail promise: serializes mutating ops so the\n  // read -> guard -> write window cannot interleave (one concurrent writer\n  // wins, the rest observe the new version and reject as stale).\n  private readonly locks = new Map<string, Promise<void>>()\n\n  constructor(ctx: Context, config: MirageFsConfig = {}) {\n    super(ctx)\n    this.cwd = config.cwd ?? '/'\n    this.sessionId = config.sessionId\n    this.diffBasisMaxBytes = config.diffBasisMaxBytes ?? DEFAULT_DIFF_BASIS_MAX_BYTES\n  }\n\n  // The workspace may still be building (declarative mounts resolve\n  // asynchronously), so every entry point awaits the service's `ready`\n  // once and caches the dispatcher. The caller's signal can fire during\n  // that wait, after its entry assertion passed, so it is asserted\n  // again here, before the op it guards dispatches.\n  //\n  // `ready` does not hydrate: a workspace freshly attached to a shared\n  // store still holds a minted default session and an empty link table\n  // until its first op loads both. This adapter reads the links off the\n  // dispatcher's reader outside a dispatch, so it hydrates before they are\n  // consulted, or a persisted hide would be judged by the wrong session.\n  private async files(signal?: AbortSignal, operation = 'ready'): Promise<Files> {\n    if (this.fsOps === null) {\n      const host = await this.ctx.mirage.ready\n      await host.ensureSessionsLoaded()\n      await host.namespace.ensureLoaded()\n      this.fsOps = this.sessionId === undefined ? host.vfs : new Session(host, this.sessionId).vfs\n    }\n    assertNotAborted(signal, operation)\n    return this.fsOps\n  }\n\n  /**\n   * The namespace as the session this adapter's ops run as sees it: the\n   * dispatcher's reader, so a link the session cannot see is never followed\n   * (the typed path reaches the dispatcher and is refused as absent, not\n   * resolved to the visible target it points at), and never listed.\n   */\n  private get reader(): ReturnType<typeof readerOf> {\n    if (this.fsOps === null) {\n      throw new Error('mirage: filesystem used before the workspace is ready')\n    }\n    return readerOf(this.fsOps)\n  }\n\n  /**\n   * The same confinement claim `MirageShellExecutor` makes, off the same\n   * fact and for the same reason: with every runtime reaching only the\n   * vfs, a mutation cannot land anywhere but a mount, under its mode.\n   *\n   * The two seams sit over one world, so answering differently here\n   * would let dsh fence a bash write and wave an identical `ctx.fs`\n   * write straight through.\n   */\n  override get sandboxMode(): FileSystem['sandboxMode'] {\n    return this.ctx.mirage.vfsOnly ? 'workspace-write' : undefined\n  }\n\n  /**\n   * Refuse a mutation the call's sandbox policy does not allow.\n   *\n   * `workspaceRoot` is deliberately not consulted: it is a directory on\n   * the harness's own machine, so containment against it says nothing\n   * about this world. The mounts and their modes are the boundary, and\n   * `read-only` is the one mode that narrows them further. Wording and\n   * code mirror `dsh-fs-sandbox`, so the tool layer renders one denial\n   * marker whichever backend refused.\n   *\n   * @param policy the per-call policy, absent for an unguarded mutation.\n   * @param displayPath the path to name in the refusal.\n   */\n  private assertMutable(policy: SandboxPolicy, displayPath: string): void {\n    if (policy?.mode !== 'read-only') return\n    throw new FsError(\n      `cannot write \"${displayPath}\": file access denied under read-only mode`,\n      'FS_SANDBOX_DENIED',\n    )\n  }\n\n  /**\n   * The base a relative path resolves against.\n   *\n   * dsh hands `ctx.fs` either the calling session's cwd or the sandbox\n   * policy's workspace root, and both are directories on the harness's\n   * own machine that name nothing here. Resolving `notes.txt` against\n   * one yields `/Users/.../notes.txt`, which every read then reports as\n   * absent. So a base that is not a directory in this world falls back\n   * to the configured one, the same rule the shell executor applies to\n   * a workdir.\n   *\n   * An absolute path ignores its base, so it never pays for the probe.\n   *\n   * @param path the path being resolved.\n   * @param cwd the caller's base, if any.\n   * @returns the base to resolve against.\n   */\n  private async resolveBase(path: string, cwd: string | undefined): Promise<string> {\n    if (cwd === undefined || posix.isAbsolute(path)) return this.cwd\n    // Probed as the session this adapter reads as: a directory only the\n    // named session can see is a base here, and one it cannot see is not.\n    return (await (await this.files()).isDir(cwd)) ? cwd : this.cwd\n  }\n\n  private normalize(path: string, base: string): string {\n    return posix.resolve(base, path)\n  }\n\n  private follow(path: string): string {\n    try {\n      return posixNormpath(this.reader.follow(path))\n    } catch (err) {\n      throw mapMirageError(err, 'resolve', path)\n    }\n  }\n\n  private withLock<T>(key: FsTargetKey, body: () => Promise<T>): Promise<T> {\n    const mapKey = String(key)\n    const previous = this.locks.get(mapKey) ?? Promise.resolve()\n    const next = previous.then(body, body)\n    // The stored tail is void (an outcome would pin whole file contents in\n    // the map) and drops on settlement unless a newer op queued behind it.\n    const tail = next.then(\n      () => undefined,\n      () => undefined,\n    )\n    this.locks.set(mapKey, tail)\n    void tail.then(() => {\n      if (this.locks.get(mapKey) === tail) this.locks.delete(mapKey)\n    })\n    return next\n  }\n\n  async resolve(path: string, opts?: { cwd?: string; signal?: AbortSignal }): Promise<FsTarget> {\n    assertNotAborted(opts?.signal, 'resolve')\n    await this.files(opts?.signal, 'resolve')\n    const followed = this.follow(this.normalize(path, await this.resolveBase(path, opts?.cwd)))\n    return { targetKey: FsTargetKey(followed), displayPath: followed }\n  }\n\n  processPath(target: FsTarget): string {\n    return String(target.targetKey)\n  }\n\n  /**\n   * The workspace path naming the same file as `hostPath`, when a mount\n   * puts one there.\n   *\n   * Most of this world has no host spelling at all: an S3 key, a Slack\n   * message and a Notion row are not files the harness could open, and\n   * claiming otherwise would hand the caller a path that reads as the\n   * wrong bytes. A disk mount is the one place the two worlds hold the\n   * same file, so it is the one place a host path is answerable; every\n   * other mount declines, and so does a workspace still building.\n   *\n   * @param hostPath absolute path in the harness host filesystem.\n   * @returns the virtual path for the same file, or undefined when no\n   *   mount maps it.\n   */\n  override processPathFromHostPath(hostPath: string): string | undefined {\n    if (!isAbsolute(hostPath)) return undefined\n    const workspace = this.ctx.mirage.workspaceIfReady\n    if (workspace === null) return undefined\n    const host = resolve(hostPath)\n    const mounts = workspace.mounts()\n    for (const entry of mounts) {\n      const { vfs } = entry\n      if (!(vfs instanceof DiskVFS)) continue\n      const rel = relative(vfs.root, host)\n      if (escapesRoot(rel)) continue\n      // `prefix` always carries a trailing slash, and `rel` is empty for\n      // the root itself, so the join is a concatenation and the slash is\n      // trimmed back off unless the mount is the workspace root.\n      const joined = `${entry.prefix}${rel.split(sep).join('/')}`\n      const virtual = joined.length > 1 && joined.endsWith('/') ? joined.slice(0, -1) : joined\n      // A mount nested under this one owns its own subtree, and dispatch\n      // routes the path there, so the disk file at this host location is\n      // not what the virtual path reads. Keep looking rather than name a\n      // path that answers with another VFS's bytes.\n      if (ownerPrefixOf(virtual, mounts) !== entry.prefix) continue\n      // A namespace symlink at or above this path is followed before\n      // dispatch, so a read would land on the link's target rather than\n      // the disk file the caller named. Links are namespace state, so the\n      // disk mount cannot see one and only this table can say.\n      if (shadowedByLink(workspace.namespace, virtual)) continue\n      return virtual\n    }\n    return undefined\n  }\n\n  fileUrl(target: FsTarget): string {\n    const encoded = String(target.targetKey).split('/').map(encodeURIComponent).join('/')\n    return `file://${encoded}`\n  }\n\n  contains(parent: FsTarget, child: FsTarget): boolean {\n    const parentKey = String(parent.targetKey)\n    const childKey = String(child.targetKey)\n    if (parentKey === childKey) return true\n    const prefix = parentKey === '/' ? '/' : `${parentKey}/`\n    return childKey.startsWith(prefix)\n  }\n\n  async stat(target: FsTarget, signal?: AbortSignal): Promise<FsInfo | undefined> {\n    assertNotAborted(signal, 'stat')\n    const key = String(target.targetKey)\n    let stat: FileStat\n    try {\n      stat = await (await this.files(signal, 'stat')).stat(key)\n    } catch (err) {\n      if (isMissingPath(err)) return undefined\n      throw mapMirageError(err, 'stat', target.displayPath)\n    }\n    return {\n      version: versionOf(stat),\n      type: typeOf(stat),\n      ...(stat.size !== null ? { size: stat.size } : {}),\n    }\n  }\n\n  async lstat(\n    path: string,\n    opts?: { cwd?: string },\n    signal?: AbortSignal,\n  ): Promise<FsPathInfo | undefined> {\n    assertNotAborted(signal, 'lstat')\n    await this.files(signal, 'lstat')\n    const normalized = this.normalize(path, await this.resolveBase(path, opts?.cwd))\n    // Follow every component except the last: the probe is about the path\n    // entry itself, so a link at the leaf must report as one.\n    const parentFollowed =\n      normalized === '/'\n        ? '/'\n        : posix.join(this.follow(posix.dirname(normalized)), posix.basename(normalized))\n    // The leaf is read off the dispatcher's reader: a link the session cannot\n    // see is not a link here, and the stat below reports it absent.\n    const linkTarget = this.reader.readlink(parentFollowed)\n    if (linkTarget !== null) {\n      return {\n        version: FsVersion(`link:${linkTarget}`),\n        type: 'symlink',\n        size: new TextEncoder().encode(linkTarget).byteLength,\n      }\n    }\n    let stat: FileStat\n    try {\n      stat = await (await this.files(signal, 'lstat')).stat(parentFollowed)\n    } catch (err) {\n      if (isMissingPath(err)) return undefined\n      throw mapMirageError(err, 'lstat', normalized)\n    }\n    return {\n      version: versionOf(stat),\n      type: typeOf(stat) === 'directory' ? 'directory' : typeOf(stat),\n      ...(stat.size !== null ? { size: stat.size } : {}),\n    }\n  }\n\n  async readText(target: FsTarget, signal?: AbortSignal): Promise<string> {\n    assertNotAborted(signal, 'read')\n    const key = String(target.targetKey)\n    let bytes: Uint8Array\n    try {\n      bytes = await (await this.files(signal, 'read')).read(key)\n    } catch (err) {\n      throw mapMirageError(err, 'read', target.displayPath)\n    }\n    return decodeStrictText(bytes, target.displayPath)\n  }\n\n  async streamText(target: FsTarget, signal?: AbortSignal): Promise<AsyncIterable<string>> {\n    // mirage reads land as one rendered buffer, so streaming is a single\n    // chunk with readText's exact text semantics.\n    const text = await this.readText(target, signal)\n    return singleChunk(text)\n  }\n\n  /**\n   * Stat a read target and refuse anything that is not a regular file.\n   *\n   * A backend read of a directory key surfaces as a missing path, which\n   * would report a path that plainly exists as absent.\n   *\n   * @param target the resolved target about to be read.\n   * @param signal aborts the stat.\n   * @returns the stat row, or undefined when the mount reports none.\n   */\n  private async statRegularFile(\n    target: FsTarget,\n    signal: AbortSignal | undefined,\n  ): Promise<FsInfo | undefined> {\n    const info = await this.stat(target, signal)\n    if (info !== undefined && info.type !== 'file') {\n      throw new FsError(\n        `cannot read \"${target.displayPath}\": not a regular file`,\n        'FS_NOT_REGULAR_FILE',\n      )\n    }\n    return info\n  }\n\n  async readBytes(\n    target: FsTarget,\n    signal: AbortSignal | undefined,\n    maxBytes: number,\n  ): Promise<Uint8Array> {\n    assertNotAborted(signal, 'read')\n    const info = await this.statRegularFile(target, signal)\n    if (info?.size !== undefined && info.size > maxBytes) {\n      throw tooLarge(target.displayPath, maxBytes, info.size)\n    }\n    // Ask for one byte past the cap rather than the whole object: a backend\n    // with a native range fetches only that window, and a full-length answer\n    // is itself the proof the file is over the cap, which is what a mount\n    // reporting no size (most API mounts) has no other way to establish.\n    const key = String(target.targetKey)\n    let bytes: Uint8Array\n    try {\n      bytes = await (await this.files(signal, 'read')).read(key, { size: maxBytes + 1 })\n    } catch (err) {\n      throw mapMirageError(err, 'read', target.displayPath)\n    }\n    if (bytes.byteLength > maxBytes) {\n      throw tooLarge(target.displayPath, maxBytes)\n    }\n    return bytes\n  }\n\n  async readByteRange(\n    target: FsTarget,\n    range: { offset: number; length: number },\n    signal?: AbortSignal,\n  ): Promise<Uint8Array> {\n    assertNotAborted(signal, 'read')\n    await this.statRegularFile(target, signal)\n    // No store can spell an empty range, so the known answer is given here\n    // rather than sent to a backend that would have to refuse it.\n    if (range.length === 0) return new Uint8Array(0)\n    // The window is the bound, not the file: the dispatcher asks a native range\n    // when the backend has one and slices a rendered read when it does not,\n    // and turns a store's past-EOF refusal into the empty POSIX answer either\n    // way, so every mount answers this the same.\n    try {\n      return await (\n        await this.files(signal, 'read')\n      ).read(String(target.targetKey), { offset: range.offset, size: range.length })\n    } catch (err) {\n      throw mapMirageError(err, 'read', target.displayPath)\n    }\n  }\n\n  async listDir(target: FsTarget, signal?: AbortSignal): Promise<FsDirEntry[]> {\n    assertNotAborted(signal, 'list')\n    const key = String(target.targetKey)\n    const info = await this.stat(target, signal)\n    if (info === undefined) {\n      throw new FsError(\n        `cannot list \"${target.displayPath}\": no such file or directory`,\n        'FS_NOT_FOUND',\n      )\n    }\n    if (info.type !== 'directory') {\n      throw new FsError(`cannot list \"${target.displayPath}\": not a directory`, 'FS_NOT_DIRECTORY')\n    }\n    let children: string[]\n    try {\n      children = await (await this.files(signal, 'list')).readdir(key)\n    } catch (err) {\n      throw mapMirageError(err, 'list', target.displayPath)\n    }\n    const names = new Set<string>()\n    for (const childPath of children) {\n      names.add(posix.basename(childPath))\n    }\n    // Namespace symlinks live above every backend, so a listing merges\n    // them in here exactly as mirage's own ls does.\n    for (const name of this.reader.linkNamesUnder(key)) names.add(name)\n    const entries: FsDirEntry[] = []\n    for (const name of [...names].sort(compareCodePoints)) {\n      // Per entry, not just at the entry point: a listing is one classification\n      // round trip per child on a backend the readdir did not warm, and\n      // a caller that gave up should stop paying for them.\n      assertNotAborted(signal, 'list')\n      entries.push(await this.dirEntry(key, name, signal))\n    }\n    return entries\n  }\n\n  private async dirEntry(\n    parentKey: string,\n    name: string,\n    signal?: AbortSignal,\n  ): Promise<FsDirEntry> {\n    const childPath = parentKey === '/' ? `/${name}` : `${parentKey}/${name}`\n    let followed: string\n    try {\n      followed = this.follow(childPath)\n    } catch {\n      // A cyclic link must not reject the whole listing; it lists as an\n      // entry of unknown kind keyed on its own path.\n      return {\n        name,\n        type: 'other',\n        target: { targetKey: FsTargetKey(childPath), displayPath: childPath },\n      }\n    }\n    const target: FsTarget = { targetKey: FsTargetKey(followed), displayPath: childPath }\n    let stat: FileStat\n    try {\n      stat = await (await this.files(signal, 'list')).stat(followed)\n    } catch (err) {\n      // An abort is the caller withdrawing, not a child this listing\n      // failed to classify, so it ends the walk instead of landing as\n      // one more entry of unknown kind.\n      if (err instanceof FsError && err.code === 'FS_ABORTED') throw err\n      // A child the listing named but stat cannot classify (a broken link,\n      // a race with a delete) still lists, as an entry of unknown kind.\n      return { name, type: 'other', target }\n    }\n    return {\n      name,\n      type: typeOf(stat),\n      target,\n      version: versionOf(stat),\n      ...(stat.size !== null ? { size: stat.size } : {}),\n    }\n  }\n\n  async writeText(\n    target: FsTarget,\n    content: string,\n    expected?: FsWriteIntent,\n    signal?: AbortSignal,\n    sandboxPolicy?: SandboxPolicy,\n  ): Promise<FsWriteOutcome> {\n    return this.withLock(target.targetKey, async () => {\n      assertNotAborted(signal, 'write')\n      this.assertMutable(sandboxPolicy, target.displayPath)\n      const key = String(target.targetKey)\n      const existing = await this.stat(target, signal)\n      if (existing !== undefined && existing.type !== 'file') {\n        throw new FsError(\n          `cannot write \"${target.displayPath}\": not a regular file`,\n          'FS_NOT_REGULAR_FILE',\n        )\n      }\n      if (expected?.kind === 'createIfAbsent' && existing !== undefined) {\n        throw new FsError(\n          `cannot write \"${target.displayPath}\": file already exists`,\n          'FS_NOT_OBSERVED',\n        )\n      }\n      if (expected?.kind === 'replaceIfVersion') {\n        if (existing?.version !== expected.version) {\n          throw new FsError(\n            `cannot write \"${target.displayPath}\": file changed since it was read`,\n            'FS_STALE_VERSION',\n          )\n        }\n      }\n      const before = existing === undefined ? null : await this.diffBasis(target, content)\n      const crlf = before !== null && detectsCrlf(before)\n      try {\n        await (\n          await this.files(signal, 'write')\n        ).write(key, restoreLineEndings(normalizeLineEndings(content), crlf))\n      } catch (err) {\n        throw mapMirageError(err, 'write', target.displayPath)\n      }\n      return {\n        operation: existing === undefined ? ('create' as const) : ('update' as const),\n        version: await this.versionAfterWrite(target),\n        before: before === null ? null : normalizeLineEndings(before),\n        after: normalizeLineEndings(content),\n      }\n    })\n  }\n\n  // The overwrite-diff basis: the prior content when it is text and both\n  // sides fit the exclusive limit, else null (dsh renders a whole-file\n  // diff then). Never fails the write itself.\n  private async diffBasis(target: FsTarget, content: string): Promise<string | null> {\n    if (Buffer.byteLength(content, 'utf8') >= this.diffBasisMaxBytes) return null\n    let bytes: Uint8Array\n    try {\n      bytes = await (await this.files()).read(String(target.targetKey))\n    } catch {\n      return null\n    }\n    if (bytes.byteLength >= this.diffBasisMaxBytes) return null\n    try {\n      return decodeStrictText(bytes, target.displayPath)\n    } catch {\n      return null\n    }\n  }\n\n  private async versionAfterWrite(target: FsTarget): Promise<FsVersion> {\n    const after = await this.stat(target)\n    return after?.version ?? FsVersion(`missing:${String(target.targetKey)}`)\n  }\n\n  async editText(\n    target: FsTarget,\n    edit: FsEditRequest,\n    expected?: { version: FsVersion },\n    signal?: AbortSignal,\n    sandboxPolicy?: SandboxPolicy,\n  ): Promise<FsEditOutcome> {\n    return this.withLock(target.targetKey, async () => {\n      assertNotAborted(signal, 'edit')\n      this.assertMutable(sandboxPolicy, target.displayPath)\n      const key = String(target.targetKey)\n      const existing = await this.stat(target, signal)\n      // Stale guard before literal matching: an edit based on an old read\n      // reports FS_STALE_VERSION, not a match failure against newer content.\n      if (existing === undefined) {\n        throw new FsError(\n          `cannot edit \"${target.displayPath}\": file changed since it was read`,\n          'FS_STALE_VERSION',\n        )\n      }\n      if (existing.type !== 'file') {\n        throw new FsError(\n          `cannot edit \"${target.displayPath}\": not a regular file`,\n          'FS_NOT_REGULAR_FILE',\n        )\n      }\n      if (expected !== undefined && existing.version !== expected.version) {\n        throw new FsError(\n          `cannot edit \"${target.displayPath}\": file changed since it was read`,\n          'FS_STALE_VERSION',\n        )\n      }\n      let bytes: Uint8Array\n      try {\n        bytes = await (await this.files(signal, 'edit')).read(key)\n      } catch (err) {\n        throw mapMirageError(err, 'edit', target.displayPath)\n      }\n      const raw = decodeStrictText(bytes, target.displayPath)\n      const original = normalizeLineEndings(raw)\n      const edited = applyLiteralEdit(\n        original,\n        normalizeLineEndings(edit.oldString),\n        normalizeLineEndings(edit.newString),\n        edit.replaceAll,\n        target.displayPath,\n      )\n      try {\n        await (\n          await this.files(signal, 'edit')\n        ).write(key, restoreLineEndings(edited, detectsCrlf(raw)))\n      } catch (err) {\n        throw mapMirageError(err, 'edit', target.displayPath)\n      }\n      return {\n        version: await this.versionAfterWrite(target),\n        before: original,\n        after: edited,\n      }\n    })\n  }\n}\n"
    },
